Bien sûr, je peux vous aider à développer un plugin WordPress personnalisé avec les fonctionnalités spécifiques que vous souhaitez ajouter à votre site Web existant.

1. Type de publication personnalisé: Pour créer un nouveau type de publication personnalisé, vous devrez créer un nouveau post type dans votre plugin. Voici un exemple de code pour créer un nouveau post type appelé "nouveau_contenu":

```php
function register_new_content_post_type() {
  $args = array(
    'label' => 'Nouveau contenu',
    'public' => true,
    'menu_icon' => 'dashicons-list-view',
    'supports' => array( 'title', 'editor', 'thumbnail' )
  );
  register_post_type( 'nouveau_contenu', $args );
}
add_action( 'init', 'register_new_content_post_type' );
```

Ensuite, vous pourriez ajouter des champs personnalisés à ce nouveau type de publication grâce à des métadonnéesCustom :

```php
function add_new_content_meta_boxes( $post ) {
  add_meta_box(
    'new_content_meta_box',
    __( 'Paramètres de Nouveau contenu', 'text-domain' ),
    'render_new_content_meta_box',
    'nouveau_contenu',
    'normal',
    'high'
  );
}

function render_new_content_meta_box( $post ) {
  wp_nonce_field( basename( __FILE__ ), 'new_content_meta_box_nonce' );
  $title = get_post_meta( $post->ID, 'title', true );
  $description = get_post_meta( $post->ID, 'description', true );

  echo '<div>';
  echo '<label for="title">' . Esc_html__( 'Titre', 'text-domain' ) . '</label>';
  echo '<input type="text" id="title" name="new_content_title" value="' . Esc_attr( $title ) . '">';
  echo '</div>';

  echo '<div>';
  echo '<label for="description">' . Esc_html__( 'Description', 'text-domain' ) . '</label>';
  echo '<textarea id="description" name="new_content_description" rows="5">' . Esc_textarea( $description ) . '</textarea>';
  echo '</div>';
}

function save_new_content_meta( $post_id ) {
  if ( ! isset( $_POST['new_content_meta_box_nonce'] ) ||
      ! wp_verify_nonce( $_POST['new_content_meta_box_nonce'], basename( __FILE__ ) ) ) {
    return;
  }

  if ( ! current_user_can( 'edit_post', $post_id ) ) {
    return;
  }

  if ( isset( $_POST['new_content_title'] ) ) {
    update_post_meta( $post_id, 'title', sanitize_text_field( $_POST['new_content_title'] ) );
  }
  if ( isset( $_POST['new_content_description'] ) ) {
    update_post_meta( $post_id, 'description', sanitize_textarea_field( $_POST['new_content_description'] ) );
  }
}
add_action( 'save_post', 'save_new_content_meta' );
```

2. Nouveau widget: Pour créer un nouveau widget, vous devriez utiliser la fonction `register_widget()` de WordPress. Voici un exemple de code pour créer un nouveau widget appelé "Widget personnalisé":

```php
class Custom_Widget extends WP_Widget {

  function __construct() {
    parent::__construct(
      'custom_widget',
      __( 'Widget personnalisé', 'text-domain' ),
      array( 'description' => __( 'Un nouveau widget personnalisé pour votre site Web', 'text-domain' ) )
    );
  }

  function widget( $args, $instance ) {
    $title = apply_filters( 'widget_title', $instance['title'] );
    $description = $instance['description'];

    echo $args['before_widget'];
    if ( ! empty( $title ) ) {
      echo $args['before_title'] . $title . $args['after_title'];
    }
    if ( ! empty( $description ) ) {
      echo '<p>' . Esc_html( $description ) . '</p>';
    }
    echo $args['after_widget'];
  }

  function update( $new_instance, $old_instance ) {
    $instance = array();
    $instance['title'] = strip_tags( $new_instance['title'] );
    $instance['description'] = esc_textarea( $new_instance['description'] );

    return $instance;
  }

  function form( $instance ) {
    if ( isset( $instance['title'] ) ) {
      $title = $instance['title'];
    } else {
      $title = __( 'Titre', 'text-domain' );
    }

    if ( isset( $instance['description'] ) ) {
      $description = $instance['description'];
    } else {
      $description = __( 'Description', 'text-domain' );
    }

    ?>
    <p>
      <label for="<?php echo $this->get_field_id( 'title' ); ?>"><?php _e( 'Titre:' ); ?></label>
      <input class="widefat" id="<?php echo $this->get_field_id( 'title' ); ?>" name="<?php echo $this->get_field_name( 'title' ); ?>" type="text" value="<?php echo esc_attr( $title ); ?>">
    </p>
    <p>
      <label for="<?php echo $this->get_field_id( 'description' ); ?>"><?php _e( 'Description:' ); ?></label>
      <textarea class="widefat" id="<?php echo $this->get_field_id( 'description' ); ?>" name="<?php echo $this->get_field_name( 'description' ); ?>" rows="5"><?php echo esc_textarea( $description ); ?></textarea>
    </p>
    <?php
  }
}

// Register and load the widget.
function register_custom_widget() {
  register_widget( 'Custom_Widget' );
}
add_action( 'widgets_init', 'register_custom_widget' );
```

3. Codes courts supplémentaires: Pour ajouter des codes courts supplémentaires, vous pouvez créer un cadre personnalisé dans votre plugin en utilisant la fonction `register_excerpt_filter()` et `add_filter()` de WordPress. Voici un exemple de code pour créer un nouveau cadre de codes courts appelé "code_court_nouveau":

```php
function register_new_excerpt_filter() {
  add_filter( 'get_the_excerpt', 'my_new_excerpt_filter', 10, 2 );
}

function my_new_excerpt_filter( $excerpt, $post ) {
  if ( has_post_format( 'video' ) ) {
    $post_content = get_post_field( 'post_content', $post->ID );
    preg_match( '/<p.*?class="wp-video-shortcode".*?>(.*?)<\/p>/', $post_content, $matches );
    if ( ! empty( $matches[1] ) ) {
      $excerpt = $matches[1];
    }
  }
  return $excerpt;
}
add_action( 'init', 'register_new_excerpt_filter' );
```

Cette fonction vérifiera s'il s'agit d'un format de publication vidéo et, si c'est le cas, remplacera l'extrait actuel par le contenu du bloc vidéo.

