```typescript
import { ExpressMiddlewareInterface, MiddlewareFunction } from '@nestjs/common';
import jwt from 'jsonwebtoken';
import { Request, Response, NextFunction } from 'express';

export class AuthGuard implements ExpressMiddlewareInterface {
  resolve(): MiddlewareFunction {
    return (req: Request, res: Response, next: NextFunction) => {
      try {
        const token = req.headers.authorization?.split(' ')[1] as string;

        if (!token) {
          return res.status(401).json({ message: 'No token provided' });
        }

        jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
          if (err) {
            return res.status(401).json({ message: 'Could not validate token' });
          }

          req.jwt_user = decoded;
          next();
        });
      } catch (err) {
        return res.status(500).json({ message: 'Internal server error' });
      }
    };
  }
}
```

