                                message: `Avoid calling setData or setDataSync methods in the beforeUpdate hook`,
                                fix(fixer) {
                                  return fixer.replaceText(methodCall, 'this.$forceUpdate()');
                                },
                              });
                            }
                          }
                        }
                      }
                    }
                  });
                }
              }

              if (/^(before|activated|deactivated)$/.test(modifierValue)) {
                // Check for state modification in non-rendered hooks
                const body = context.getAncestorByType('Program')?.body;

                if (body) {
                  const statements = body.body;

                  checkStateChangedStatements(statements);
                }
              }
            }
          },
        };
      },
    },
  },
};

function checkStateChangedStatements(statements) {
  statements.forEach((statement) => {
    switch (statement.type) {
      case 'BlockStatement':
        const blockStatements = statement.body;

        blockStatements.forEach((blockStatement) => {
          switch (blockStatement.type) {
            case 'VariableDeclaration':
              blockStatement.declarations.forEach((declaration) => {
                if (declaration.init && (declaration.init.type === 'ArrayExpression' || declaration.init.type === 'ObjectExpression')) {
                  context.report({
                    node: statement,
                    message: `Avoid setting internal component state in the {{hookName}} hook.`,
                    fix(fixer) {
                      const { range } = statement;

                      return fixer.insertBefore(range[1], '\nthis.$forceUpdate()');
                    },
                    data: { hookName: getHookName(statement) },
                  });
                }
              });
              break;
            case 'ExpressionStatement':
              const expressionStatement = blockStatement;

              if (
                expressionStatement.expression.type === 'AssignmentExpression' &&
                (expressionStatement.expression.left.type === 'MemberExpression' || expressionStatement.expression.left.type === 'Identifier')
              ) {
                context.report({
                  node: expressionStatement,
                  message: `Avoid modifying internal component state in the {{hookName}} hook. Use a computed property or a method instead.`,
                  fix(fixer) {
                    const { range } = expressionStatement.expression;

                    return fixer.replaceText(range[0], 'this');
                  },
                  data: { hookName: getHookName(statement) },
                });
              }

              checkStateChangedExpressions(expressionStatement.expression);
              break;
          }
        });
        break;
      case 'ExpressionStatement':
        checkStateChangedExpressions(statement.expression);
        break;
    }
  });
}

function checkStateChangedExpressions(expression) {
  switch (expression.type) {
    case 'MemberExpression':
      const property = expression.object;

      if (property.type === 'ThisExpression') {
        const propertyValue = expression.property;

        if (propertyValue.name === 'data') {
          context.report({
            node: expression,
            message: `Avoid modifying internal component state in this hook. Use a computed property or a method instead.`,
            fix(fixer) {
              const { range } = expression;

              return fixer.replaceRange(
                range.toString(),
                '$.e = this.$data'
              );
            },
          });
        }

        if (propertyValue.name === '$data') {
          context.report({
            node: expression,
            message: `Avoid modifying internal component state in this hook. Use a computed property or a method instead.`,
            fix(fixer) {
              const { range } = expression;

              return fixer.replaceRange(
                range.toString(),
                '$e = this.$data'
              );
            },
          });
        }

        if (expression.property.type === 'Identifier' && expression.computed) {
          const propertyValue = expression.property.name;

          if (['$set', '$forceUpdate'].includes(propertyValue)) {
            return;
          }

          context.report({
            node: expression,
            message: `Avoid calling internal state modification methods in this hook.`,
            fix(fixer) {
              const { range } = expression;

              return fixer.replaceText(range[0], 'this');
            },
          });
        }
      }
      break;
    case 'CallExpression':
      const callee = expression.callee;

      if (callee.type === 'MemberExpression') {
        const object = callee.object;

        if (object.type === 'ThisExpression') {
          const propertyName = callee.property.name;

          if (propertyName === 'setData' || propertyName === 'setDataSync') {
            context.report({
              node: expression,
              message: `Avoid calling setData or setDataSync methods in this hook.`,
              fix(fixer) {
                const { range } = expression;

                return fixer.replaceText(range[0], 'this.$forceUpdate()');
              },
            });
          }
        }
      }
      break;
    case 'ObjectExpression':
      expression.properties.forEach((property) => {
        if (
          property.type === 'Property' &&
          property.key.type === 'Identifier' &&
          ['data'].includes(property.key.name)
        ) {
          context.report({
            node: property,
            message: `Avoid modifying internal component state directly. Use a computed property or a method instead.`,
            fix(fixer) {
              const { range } = property.value;

              return fixer.insertAfter(range[1], '\nconst tempData = this.$data');
            },
          });
        }
      });
      break;
  }
}

function getHookName(node) {
  const parent = node.parent;

  if (parent?.type === 'HookName') {
    const hooktext = parent.value;

    return `${hooktext.value.slice(0, -1).replace(/_/g, ' ')} Hook`;
  }

  return '';
}
